/**
 * What the executor does next. Returned by [`UploadPlanner::next_actions`](super::UploadPlanner::next_actions).
 *
 * The executor runs a returned list in order. `Wait` pauses the rest of that list (sends in flight
 * continue), then the executor calls `next_actions` again after each result.
 */
sealed class Action {
    
    /**
     * Upload block `i` (`PUT` of the block, ack only on 204).
     */
    data class SendBlock(
        val `i`: kotlin.UInt) : Action()
        
    {
        

        companion object
    }
    
    /**
     * Sleep `ms` before the actions that follow in the same list. Carries the server's `retry_after`
     * as given, or the backoff computed from [`RetryPolicy`]; jitter is the executor's.
     */
    data class Wait(
        val `ms`: kotlin.ULong) : Action()
        
    {
        

        companion object
    }
    
    /**
     * Call `get_upload` and feed the answer to `on_session`.
     */
    object RereadSession : Action()
    
    
    /**
     * All needed blocks are acked and nothing is in flight: commit, then feed `on_commit`.
     */
    object Commit : Action()
    
    
    /**
     * Terminal: the commit succeeded.
     */
    object Done : Action()
    
    
    /**
     * Terminal: abandon this planner, start a new session with the same `client_key` and build a new
     * planner from the answer. After `BlocklistMismatch` the caller re-hashes the file first.
     */
    object RestartSession : Action()
    
    
    /**
     * Terminal: block `i` used up `max_attempts_per_block` sends without an ack, so the planner stops
     * retrying it instead of emitting another `SendBlock`.
     *
     * Decision for `sync_core_proto.md` open point 2: the executor stops the transfer, cancels the
     * requests in flight, keeps the checkpoint and the `client_key`, and reports a retryable
     * "block upload failed" error to its caller. A later run starts with a new planner (attempt counts
     * start again), so the file is retried only when the host schedules it.
     */
    data class GiveUp(
        val `i`: kotlin.UInt) : Action()
        
    {
        

        companion object
    }
    

    

    
    


    companion object
}

/**
 * @suppress
 */
public object FfiConverterTypeAction : FfiConverterRustBuffer<Action>{
    override fun read(buf: ByteBuffer): Action {
        return when(buf.getInt()) {
            1 -> Action.SendBlock(
                FfiConverterUInt.read(buf),
                )
            2 -> Action.Wait(
                FfiConverterULong.read(buf),
                )
            3 -> Action.RereadSession
            4 -> Action.Commit
            5 -> Action.Done
            6 -> Action.RestartSession
            7 -> Action.GiveUp(
                FfiConverterUInt.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: Action): ULong = when(value) {
        is Action.SendBlock -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`i`)
            )
        }
        is Action.Wait -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterULong.allocationSize(value.`ms`)
            )
        }
        is Action.RereadSession -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Action.Commit -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Action.Done -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Action.RestartSession -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
            )
        }
        is Action.GiveUp -> {
            // Add the size for the Int that specifies the variant plus the size needed for all fields
            (
                4UL
                + FfiConverterUInt.allocationSize(value.`i`)
            )
        }
    }

    override fun write(value: Action, buf: ByteBuffer) {
        when(value) {
            is Action.SendBlock -> {
                buf.putInt(1)
                FfiConverterUInt.write(value.`i`, buf)
                Unit
            }
            is Action.Wait -> {
                buf.putInt(2)
                FfiConverterULong.write(value.`ms`, buf)
                Unit
            }
            is Action.RereadSession -> {
                buf.putInt(3)
                Unit
            }
            is Action.Commit -> {
                buf.putInt(4)
                Unit
            }
            is Action.Done -> {
                buf.putInt(5)
                Unit
            }
            is Action.RestartSession -> {
                buf.putInt(6)
                Unit
            }
            is Action.GiveUp -> {
                buf.putInt(7)
                FfiConverterUInt.write(value.`i`, buf)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
}







sealed class BatchIdException: kotlin.Exception() {
    
    class NotV7(
        ) : BatchIdException() {
        override val message
            get() = ""
    }
    
    class EqualsMemberKey(
        ) : BatchIdException() {
        override val message
            get() = ""
    }
    

    


    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<BatchIdException> {
        override fun lift(error_buf: RustBuffer.ByValue): BatchIdException = FfiConverterTypeBatchIdError.lift(error_buf)
    }

    
}

/**
 * @suppress
 */
public object FfiConverterTypeBatchIdError : FfiConverterRustBuffer<BatchIdException> {
    override fun read(buf: ByteBuffer): BatchIdException {
        

        return when(buf.getInt()) {
            1 -> BatchIdException.NotV7()
            2 -> BatchIdException.EqualsMemberKey()
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: BatchIdException): ULong {
        return when(value) {
            is BatchIdException.NotV7 -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
            is BatchIdException.EqualsMemberKey -> (
                // Add the size for the Int that specifies the variant plus the size needed for all fields
                4UL
            )
        }
    }

    override fun write(value: BatchIdException, buf: ByteBuffer) {
        when(value) {
            is BatchIdException.NotV7 -> {
                buf.putInt(1)
                Unit
            }
            is BatchIdException.EqualsMemberKey -> {
                buf.putInt(2)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}



/**
 * Outcome of one block `PUT`, as mapped by the executor from the wire.
 */
sealed class BlockResult {
    
    /**
     * 204: the block is durable on the server.
     */
